{
  "name": "cybertron-agents",
  "version": "0.3.0",
  "description": "Install the 13 Cybertron Primes agents and the /cybertron command into OpenCode",
  "type": "module",
  "bin": {
    "cybertron": "bin/cybertron.mjs"
  },
  "files": [
    "bin",
    "lib",
    "payload",
    "install.sh"
  ],
  "scripts": {
    "prepack": "node scripts/build-payload.mjs"
  },
  "engines": {
    "node": ">=18"
  },
  "keywords": [
    "opencode",
    "agents",
    "cybertron",
    "multi-agent"
  ],
  "repository": {
    "type": "git",
    "url": "https://github.com/zhiwenC125/Cybertron-agents"
  },
  "license": "MIT"
}

{
  "name": "@local/cybertron-dsh",
  "version": "0.1.0",
  "private": true,
  "type": "module",
  "description": "Cybertron v6 ledger tools for DeepSeek Harness",
  "exports": {
    ".": "./index.js",
    "./locale/*.json": "./locale/*.json",
    "./icon": "./icon.svg"
  },
  "files": [
    "index.js",
    "bridge.js",
    "cordis.patch.yml",
    "locale/*.json",
    "docs",
    "icon.svg"
  ],
  "dsh": {
    "bundle": {
      "patch": "./cordis.patch.yml"
    }
  }
}

